// BUFFER STAGE 3: Map connected channels by platform service name
// Input:  GraphQL response from channels query (data.channels array)
// Output: Structured object with channel IDs per platform + content data

const rawData = $input.first().json;
const channelList = rawData?.data?.channels || [];

// Map each service to its channel ID (first connected channel per platform wins)
const channelMap = {};
for (const channel of channelList) {
  const service = (channel.service || '').toLowerCase();
  const id = channel.id;
  if (service && id && !channelMap[service]) {
    channelMap[service] = {
      id: String(id),
      name: channel.displayName || channel.name || service,
      service: service
    };
  }
}

// Pull captions and image URL from the upstream Build Final Output node
const content = $('Build Final Output (JSON)').item.json;
const postId = $('Workflow Context')?.item?.json?.post_id || '';

// Structured logging for observability
console.log('[Buffer] Channels retrieved:', JSON.stringify(Object.keys(channelMap)));
console.log('[Buffer] instagram_channel_id:', channelMap['instagram']?.id || 'NOT CONNECTED');
console.log('[Buffer] facebook_channel_id:', channelMap['facebook']?.id || 'NOT CONNECTED');
console.log('[Buffer] linkedin_channel_id:', channelMap['linkedin']?.id || 'NOT CONNECTED');
console.log('[Buffer] tiktok_channel_id:', channelMap['tiktok']?.id || 'NOT CONNECTED');
console.log('[Buffer] twitter_channel_id:', channelMap['twitter']?.id || 'NOT CONNECTED');
console.log('[Buffer] image_url:', content.image_url || 'MISSING');
console.log('[Buffer] instagram_post length:', (content.instagram_post || '').length);
console.log('[Buffer] facebook_post length:', (content.facebook_post || '').length);
console.log('[Buffer] linkedin_post length:', (content.linkedin_post || '').length);
console.log('[Buffer] tiktok_post length:', (content.tiktok_post || '').length);

return [{
  json: {
    // Supabase post_id for DB status update
    post_id: postId,
    // Buffer channel IDs per platform (null = platform not connected in Buffer)
    instagram_profile_id: channelMap['instagram']?.id || null,
    facebook_profile_id:  channelMap['facebook']?.id  || null,
    linkedin_profile_id:  channelMap['linkedin']?.id  || null,
    tiktok_profile_id:    channelMap['tiktok']?.id    || null,
    twitter_profile_id:   channelMap['twitter']?.id   || null,
    // All channels for reference and DB logging
    all_profiles: channelMap,
    profiles_retrieved_at: new Date().toISOString(),
    // Platform-specific captions â€” correctly mapped, never mixed between platforms
    instagram_post: content.instagram_post || '',
    facebook_post:  content.facebook_post  || '',
    linkedin_post:  content.linkedin_post  || '',
    tiktok_post:    content.tiktok_post    || '',
    // Existing verified Supabase public image URL â€” no re-upload, no regeneration
    image_url: content.image_url || '',
    topic: content.topic || '',
    generated_at: content.generated_at || '',
    workflow_started_at: content.workflow_started_at || ''
  }
}];

