const output = $input.first().json;
const allowed = $('VIVENT Campaign Context').item.json.platforms || [];
const captions = { instagram: output.instagram_post, facebook: output.facebook_post, linkedin: output.linkedin_post, tiktok: output.tiktok_post };
return allowed.filter(platform => captions[platform]).map(platform => ({ json: { ...output, platform, caption: captions[platform] } }));
